/// Pumps the onboarding flow full-screen with the app's real theme and
/// localization; [keysStore] is exposed through a [SessionKeysScope] like
/// the app shell does.
Future<void> _pumpOnboarding(
  WidgetTester tester, {
  OnboardingStore? onboardingStore,
